const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['組社團第一步要做什麼','30 位以上'],['我想成立一個協會要從哪裡開始','第8條'],['想組協會要先做什麼','發起人'],
 ['發起人要不要都住屏東','設籍'],['發起人可以是外國人嗎','沒有寫國籍限制'],['發起人一定要住本縣嗎','工作證明'],
 ['申請籌組要多久才會核准','2 個月'],['籌組申請送件後多久審查完','審查期限'],
 ['籌組許可下來後多久內要成立','6 個月'],['許可後要在幾個月內成立','逾期'],['籌組申請審查要多久','2 個月'],['來不及成立可以延嗎','最多延 3 個月'],['籌組失敗了怎麼辦','廢止'],
 ['成立大會要通知誰','派員列席'],['成立大會要提前幾天通知','15 天前'],
 ['成立之後多久要報縣府立案','30 日'],['立案要附什麼文件','選任職員簡歷冊'],['成立大會後要準備哪些文件報縣府','會址同意書'],
 ['立案證書什麼時候拿','沒有訂'],['章程草案誰來擬','發起人'],['協會名稱可以隨便取嗎','第7條'],['名稱跟別人重複怎麼辦','相同'],
 ['籌備期間可以收會費嗎','沒有明文'],['籌備會的錢誰出','沒有明文'],['成立之前可以先收錢嗎','第33條'],
 ['沒登記法人可以買房子嗎','不敢直接答'],['協會沒有法人登記能買土地嗎','地政事務所']
];
const no=['協會可以取英文名稱嗎','協會簡稱可以隨便取嗎','合作社成立要幾個人','公會籌組第一步','社區發展協會成立第一步','協會想買房子第一步要確認什麼','協會成立後怎麼開戶','協會要改名怎麼辦','協會會費可以調漲嗎','理事長任期多久','怎麼申請統編','協會補助申請要多久','勸募要多久核准','已成立的協會立案證書遺失怎麼辦','成立要花多少錢','籌備會要開幾次'];
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const txt=a?(a.title+a.summary):'';if(!txt.includes(e)||!a.direct){bad++;console.log('✗',q,a&&a.title)}});
const mine=/(沒有法人登記可以買房子嗎|籌備期間的收費與經費|協會名稱不能隨便取|章程草案：由發起人|發起人的戶籍與身分|申請籌組送件後|許可籌組後 6 個月|成立大會要通知會員|成立大會後 30 日內|立案證書：縣府核准|成立協會的第一步)/;
no.forEach(q=>{const a=A(q);if(a&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
